def run(d, current=False):
 if current and not list(ROOT.glob('work/writer_*/selection_'+d+'.json')):raise RuntimeError('Unsealed date: '+d)
 p=ROOT/('specs'if current else'work/market_prose_snapshots')/f'{d}.json'; spec=json.loads(p.read_text());card=json.loads((ROOT/'cards'/f'{d}.json').read_text());mk=card['markets'];rows=[]
 pats=[]
 for t in mk:
  if re.fullmatch(r'[A-Z][A-Z0-9.-]*',t):pats.append((t,re.compile(r'(?<![A-Za-z0-9])'+re.escape(t)+r'(?![A-Za-z0-9])')))
  if '.' in t and t.split('.')[0].isupper():pats.append((t,re.compile(r'(?<![A-Za-z0-9])'+re.escape(t.split('.')[0])+r'(?![A-Za-z0-9])')))
 for t,als in ALIASES.items():
  for a in als:pats.append((t,re.compile(r'(?<![A-Za-z0-9])'+a+r'(?![A-Za-z0-9])',re.I)))
 for path,text in strings(spec):
  if not TAG.search(text):continue
