  for t,pat in pats:
   if path[0] in {'retail','catalysts','underowned','anticipatory'} and pat.search(spec[path[0]][path[1]]['title']):symbols.add(t)
   for m in pat.finditer(clean):symbols.add(t);mentions.append((m.start(),m.end(),t))
  vals=[];unmatched=[];flags=[]
  for n in NUM.finditer(clean):
   if any(a<=n.start()<b for a,b,t in mentions):continue
   val=float(n.group(1).replace(',','').replace('−','-'))
   after=clean[n.end():];before=clean[:n.start()]
   if re.match(r'\s*[- ]?(?:session|observations?|day|year|Y\b|M\b)',after,re.I):continue
   if re.search(r'\b(?:Q|H)$',before):continue
   if val in [2025,2026,2027]:continue
