from pathlib import Path
import json,re,gzip,sys,hashlib
ROOT=Path(__file__).resolve().parent.parent
CITE=re.compile(r'\[\[(n\d{4,6})\]\]')
MONEY=re.compile(r'(?:\d[\d,.]*\s*(?:%|bps?\b|basis points?\b|index points?\b|points?\b|USD\b|PLN\b|EUR\b|JPY\b|HKD\b|KRW\b|AUD\b|GBp\b|DKK\b)|[$€£¥]\s*\d|\b(?:PMI|PMIs|DXY|Dollar Index|dollar index|CMCSA|Comcast|CRWV|CoreWeave|yield|yields|10Y|2Y|20.session|5.session|1.session)\b)',re.I)
NUM=re.compile(r'\d')
def strings(v,path=()):
 if isinstance(v,dict):
  for k,x in v.items():yield from strings(x,path+(k,))
 elif isinstance(v,list):
  for k,x in enumerate(v):yield from strings(x,path+(k,))
 elif isinstance(v,str):yield path,v
for d in sys.argv[1:]:
 seals=list(ROOT.glob('work/writer_*/selection_'+d+'.json'))
 if not seals:print('UNSEALED',d);continue
 spec=json.loads((ROOT/'specs'/f'{d}.json').read_text());card=json.loads((ROOT/'cards'/f'{d}.json').read_text())
 print('\nDATE',d)
 for path,text in strings(spec):
  if not isinstance(path[-1],int) or len(path)<2 or not MONEY.search(CITE.sub('',text)):continue
  sentences=re.split(r'(?<=[.!?])\s+(?=[A-Z($])',text)
  pick=[s for s in sentences if MONEY.search(CITE.sub('',s)) and NUM.search(CITE.sub('',s))]
  if pick:print(json.dumps({'path':list(path),'clauses':pick},ensure_ascii=False))

